import { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import AuthContext from '../context/AuthContext';
import axios from 'axios';
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('student');
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', {
        email,
        password,
        role,
      });

      login(res.data);

      if (res.data.user.role === 'admin') {
        navigate('/admin');
      } else {
        navigate('/dashboard');
      }
    } catch (err) {
      alert('Login failed: ' + (err.response?.data?.error || 'Invalid credentials'));
    }
  };

  return (
    <div
      style={{
        height: '100vh',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        fontFamily: 'Poppins, sans-serif',
        background: 'linear-gradient(135deg, #0f172a, #1e293b)',
      }}
    >
      {/* Center Card */}
      <div
        style={{
          width: '420px',
          padding: '45px 35px',
          borderRadius: '18px',
          background: '#111827',
          boxShadow: '0 20px 50px rgba(0,0,0,0.5)',
          textAlign: 'center',
        }}
      >
        {/* Logo */}
        <img
          src="/logo.png"
          alt="logo"
          style={{
            width: '85px',
            borderRadius: '50%',
            marginBottom: '15px',
          }}
        />

        {/* Title */}
        <h2 style={{ color: '#ffffff', fontWeight: '600' }}>
          Quiz Portal
        </h2>

        <p style={{ color: '#9ca3af', fontSize: '14px', marginBottom: '30px' }}>
          Sign in to continue your journey
        </p>

        <form onSubmit={handleSubmit}>

          {/* Email */}
          <div style={{ marginBottom: '20px', textAlign: 'left' }}>
            <label style={{ color: '#9ca3af', fontSize: '13px' }}>Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              style={{
                width: '100%',
                padding: '10px',
                marginTop: '5px',
                borderRadius: '8px',
                border: '1px solid #374151',
                background: '#1f2937',
                color: 'white',
                outline: 'none',
              }}
            />
          </div>

          {/* Password */}
          <div style={{ marginBottom: '20px', textAlign: 'left' }}>
            <label style={{ color: '#9ca3af', fontSize: '13px' }}>Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              style={{
                width: '100%',
                padding: '10px',
                marginTop: '5px',
                borderRadius: '8px',
                border: '1px solid #374151',
                background: '#1f2937',
                color: 'white',
                outline: 'none',
              }}
            />
          </div>

          {/* Role */}
          <div style={{ marginBottom: '25px', textAlign: 'left' }}>
            <label style={{ color: '#9ca3af', fontSize: '13px' }}>
              Select Role
            </label>

            <div style={{ display: 'flex', gap: '10px', marginTop: '8px' }}>
              <button
                type="button"
                onClick={() => setRole('student')}
                style={{
                  flex: 1,
                  padding: '10px',
                  borderRadius: '8px',
                  border:
                    role === 'student'
                      ? '2px solid #22c55e'
                      : '1px solid #374151',
                  background:
                    role === 'student' ? '#22c55e20' : '#1f2937',
                  color: 'white',
                }}
              >
                🎓 Student
              </button>

              <button
                type="button"
                onClick={() => setRole('admin')}
                style={{
                  flex: 1,
                  padding: '10px',
                  borderRadius: '8px',
                  border:
                    role === 'admin'
                      ? '2px solid #3b82f6'
                      : '1px solid #374151',
                  background:
                    role === 'admin' ? '#3b82f620' : '#1f2937',
                  color: 'white',
                }}
              >
                🛠 Admin
              </button>
            </div>
          </div>

          {/* Button */}
          <button
            type="submit"
            style={{
              width: '100%',
              padding: '12px',
              borderRadius: '10px',
              border: 'none',
              background: 'linear-gradient(90deg, #06b6d4, #3b82f6)',
              color: 'white',
              fontWeight: '600',
              fontSize: '15px',
              marginTop: '10px',
            }}
          >
            Start Quiz →
          </button>

        </form>

        {/* Footer */}
        <div style={{ marginTop: '20px' }}>
          <span style={{ color: '#9ca3af', fontSize: '13px' }}>
            New here?{' '}
            <a href="/register" style={{ color: '#22c55e' }}>
              Join Now
            </a>
          </span>
        </div>
      </div>
    </div>
  );
}
